 layout=section(studio);add(layout,label("03 / Edição para redes sociais",19,Color.WHITE));style=choices(new String[]{"Sem edição","Viral • amarelo","Elegante • branco","Neon • roxo"});style.setSelection(1);add(layout,style);headline=new EditText(this);headline.setHint("Título do vídeo (opcional)");headline.setTextColor(Color.WHITE);headline.setFilters(new android.text.InputFilter[]{new android.text.InputFilter.LengthFilter(100)});add(layout,headline);captionText=new EditText(this);captionText.setHint("Texto fixo na parte inferior (opcional)");captionText.setTextColor(Color.WHITE);captionText.setFilters(new android.text.InputFilter[]{new android.text.InputFilter.LengthFilter(140)});add(layout,captionText);clipLength=choices(new String[]{"15 segundos","30 segundos","60 segundos"});clipLength.setSelection(2);add(layout,clipLength);
