 private void download(){String url=link.getText().toString().trim();Uri parsed=Uri.parse(url);if(!"https".equalsIgnoreCase(parsed.getScheme())||parsed.getHost()==null){status.setText("Informe um link HTTPS válido.");return;}String host=parsed.getHost().toLowerCase(java.util.Locale.ROOT);if(host.equals("youtu.be")||host.equals("youtube.com")||host.endsWith(".youtube.com")){new android.app.AlertDialog.Builder(this).setTitle("Importar do YouTube").setMessage("Confirme que você tem autorização para baixar e editar este vídeo.").setNegativeButton("Cancelar",null).setPositiveButton("Tenho autorização",(d,w)->downloadYoutube(url)).show();return;}busy=true;pick.setEnabled(false);importLink.setEnabled(false);run.setEnabled(false);status.setText("Baixando vídeo...");progress.setIndeterminate(true);new Thread(()->{File file=null;java.net.HttpURLConnection connection=null;try{file=File.createTempFile("import-",".mp4",getCacheDir());connection=(java.net.HttpURLConnection)new java.net.URL(url).openConnection();connection.setInstanceFollowRedirects(false);connection.setConnectTimeout(15000);connection.setReadTimeout(30000);if(connection.getResponseCode()!=200)throw new IOException("Link indisponível ou redirecionado");String type=connection.getContentType();if(type==null||(!type.startsWith("video/")&&!type.startsWith("application/octet-stream")))throw new IOException("O link não aponta para um vídeo");long total=0;try(InputStream in=connection.getInputStream();OutputStream out=new FileOutputStream(file)){byte[] buf=new byte[65536];int n;while((n=in.read(buf))!=-1){total+=n;if(total>500L*1024*1024)throw new IOException("Limite de 500 MB");out.write(buf,0,n);}}File ready=file;runOnUiThread(()->{if(downloaded!=null)downloaded.delete();downloaded=ready;load(Uri.fromFile(ready));});}catch(Exception e){if(file!=null)file.delete();runOnUiThread(()->finishJob("Falha no link: "+e.getMessage()));}finally{if(connection!=null)connection.disconnect();}}).start();}
 private void downloadYoutube(String url){
 if(busy)return;busy=true;pick.setEnabled(false);importLink.setEnabled(false);run.setEnabled(false);status.setText("Verificando link e preparando motor...");progress.setIndeterminate(true);
 new Thread(()->{File folder=new File(getCacheDir(),"youtube-"+System.nanoTime());try{
 if(!folder.mkdirs())throw new IOException("Sem espaço para importação");
 com.yausername.youtubedl_android.YoutubeDL.getInstance().init(getApplicationContext());
 com.yausername.ffmpeg.FFmpeg.getInstance().init(getApplicationContext());
 com.yausername.youtubedl_android.YoutubeDLRequest request=new com.yausername.youtubedl_android.YoutubeDLRequest(url);
 request.addOption("--no-playlist");request.addOption("--no-cache-dir");request.addOption("--max-filesize","500M");request.addOption("-f","best[ext=mp4][height<=720]/best[ext=mp4]");request.addOption("-o",new File(folder,"source.%(ext)s").getAbsolutePath());
 com.yausername.youtubedl_android.YoutubeDL.getInstance().execute(request,null,(percent,eta,line)->{runOnUiThread(()->{if(percent>=0 && percent<=100){progress.setIndeterminate(false);progress.setProgress(percent.intValue());status.setText("Baixando vídeo • "+percent.intValue()+"%"+(eta>=0?" • "+eta+"s restantes":""));}else{progress.setIndeterminate(true);status.setText("Verificando vídeo e formatos disponíveis...");}return;});return kotlin.Unit.INSTANCE;});
 File file=new File(folder,"source.mp4");if(!file.isFile()||file.length()==0||file.length()>500L*1024*1024)throw new IOException("Vídeo indisponível ou acima de 500 MB");
 runOnUiThread(()->{if(downloaded!=null)downloaded.delete();downloaded=file;load(Uri.fromFile(file));});
 }catch(Exception e){File[] files=folder.listFiles();if(files!=null)for(File f:files)f.delete();folder.delete();runOnUiThread(()->finishJob("Falha na importação do YouTube: "+e.getMessage()));}}).start();
 }
 private void load(Uri uri){source=null;status.setText("Analisando duração e metadados...");try(MediaMetadataRetriever m=new MediaMetadataRetriever()){m.setDataSource(this,uri);duration=Long.parseLong(m.extractMetadata(MediaMetadataRetriever.METADATA_KEY_DURATION));if(duration<=0)throw new IOException();source=uri;finishJob("Vídeo pronto • "+duration/1000+" s • "+((duration+clipMs-1)/clipMs)+" cortes");}catch(Exception e){finishJob("Não foi possível ler o vídeo.");}}
 private void card(Uri uri,int number,long from,long to){LinearLayout panel=new LinearLayout(this);panel.setOrientation(1);panel.setPadding(dp(12),dp(12),dp(12),dp(12));panel.setBackground(bg(0xff242637,16));ImageView thumb=new ImageView(this);thumb.setScaleType(ImageView.ScaleType.CENTER_CROP);thumb.setBackgroundColor(0xff38394a);panel.addView(thumb,new LinearLayout.LayoutParams(-1,dp(150)));add(panel,label("Corte "+number+"  •  "+((to-from+999)/1000)+" s",18,Color.WHITE));add(panel,label((from/1000)+"s — "+(to/1000)+"s  |  MP4 salvo",13,0xffb9bbce));Button play=action("Reproduzir");play.setOnClickListener(v->{try{Intent i=new Intent(Intent.ACTION_VIEW);i.setDataAndType(uri,"video/mp4");i.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);startActivity(i);}catch(Exception e){Toast.makeText(this,"Nenhum player disponível",Toast.LENGTH_SHORT).show();}});Button share=action("Compartilhar");share.setOnClickListener(v->{Intent i=new Intent(Intent.ACTION_SEND);i.setType("video/mp4");i.putExtra(Intent.EXTRA_STREAM,uri);i.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);startActivity(Intent.createChooser(i,"Compartilhar corte"));});Button download=action("↓  Baixar / salvar cópia");LinearLayout actions=new LinearLayout(this);actions.setOrientation(1);LinearLayout pair=new LinearLayout(this);pair.addView(play,new LinearLayout.LayoutParams(0,dp(48),1));LinearLayout.LayoutParams shareParams=new LinearLayout.LayoutParams(0,dp(48),1);shareParams.leftMargin=dp(8);pair.addView(share,shareParams);add(actions,pair);add(actions,download);add(panel,actions);download.setOnClickListener(v->{pendingExport=uri;Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT);i.setType("video/mp4");i.addCategory(Intent.CATEGORY_OPENABLE);i.putExtra(Intent.EXTRA_TITLE,"CortaClip_"+System.currentTimeMillis()+".mp4");startActivityForResult(i,20);});Button cover=action("Criar thumbnail premium");add(panel,cover);cover.setOnClickListener(v->{EditText titleInput=new EditText(this);titleInput.setHint("Título específico deste corte");titleInput.setFilters(new android.text.InputFilter[]{new android.text.InputFilter.LengthFilter(85)});new android.app.AlertDialog.Builder(this).setTitle("Capa do corte "+number).setView(titleInput).setItems(new String[]{"Vertical 9:16","Horizontal 16:9"},(dialog,which)->{String title=titleInput.getText().toString().trim();if(title.isEmpty()){Toast.makeText(this,"Informe o título da capa",Toast.LENGTH_SHORT).show();return;}cover.setEnabled(false);thumbnails.execute(()->{Uri imageUri=null;try{android.graphics.Bitmap bitmap=ThumbnailEngine.render(this,uri,title,which==0);ContentValues cv=new ContentValues();cv.put(MediaStore.Images.Media.DISPLAY_NAME,"CortaClip_Capa_"+System.currentTimeMillis()+".png");cv.put(MediaStore.Images.Media.MIME_TYPE,"image/png");cv.put(MediaStore.Images.Media.RELATIVE_PATH,"Pictures/CortaClip");cv.put(MediaStore.Images.Media.IS_PENDING,1);imageUri=getContentResolver().insert(MediaStore.Images.Media.EXTERNAL_CONTENT_URI,cv);if(imageUri==null)throw new IOException("Sem acesso");try(OutputStream out=getContentResolver().openOutputStream(imageUri)){if(out==null||!bitmap.compress(android.graphics.Bitmap.CompressFormat.PNG,100,out))throw new IOException("Falha ao salvar");}finally{bitmap.recycle();}cv.clear();cv.put(MediaStore.Images.Media.IS_PENDING,0);getContentResolver().update(imageUri,cv,null,null);Uri saved=imageUri;runOnUiThread(()->{cover.setEnabled(true);thumb.setImageURI(saved);Toast.makeText(this,"Capa salva na galeria",Toast.LENGTH_LONG).show();});}catch(Exception e){if(imageUri!=null)getContentResolver().delete(imageUri,null,null);runOnUiThread(()->{cover.setEnabled(true);Toast.makeText(this,"Erro ao criar capa",Toast.LENGTH_LONG).show();});}});}).setNegativeButton("Cancelar",null).show();});add(panel,label("PRONTO PARA PUBLICAR",11,0xff65d9ad));cards.addView(panel,0);historyCount.setText(cards.getChildCount()+" cortes na biblioteca");thumbnails.execute(()->{try{android.graphics.Bitmap image=getContentResolver().loadThumbnail(uri,new android.util.Size(480,270),null);runOnUiThread(()->thumb.setImageBitmap(image));}catch(Exception ignored){}});}
 @Override protected void onActivityResult(int r,int c,Intent d){super.onActivityResult(r,c,d);if(c!=RESULT_OK||d==null)return;if(r==20&&pendingExport!=null){Uri original=pendingExport,destination=d.getData();pendingExport=null;new Thread(()->{try(InputStream in=getContentResolver().openInputStream(original);OutputStream out=getContentResolver().openOutputStream(destination)){if(in==null||out==null)throw new IOException("Arquivo indisponível");byte[] buffer=new byte[65536];int n;while((n=in.read(buffer))!=-1)out.write(buffer,0,n);runOnUiThread(()->Toast.makeText(this,"Cópia salva",Toast.LENGTH_SHORT).show());}catch(Exception e){runOnUiThread(()->Toast.makeText(this,"Falha ao salvar cópia",Toast.LENGTH_LONG).show());}}).start();return;}if(r==10)load(d.getData());}
 private void finishJob(String message){busy=false;format.setEnabled(true);quality.setEnabled(true);pick.setEnabled(true);importLink.setEnabled(true);run.setEnabled(source!=null);progress.setIndeterminate(false);status.setText(message);}
 private void next(){if(start>=duration){finishJob(count+" cortes salvos na galeria.");showTab(true);return;}long end=Math.min(duration,start+clipMs);File temp=new File(getCacheDir(),"clip-"+System.nanoTime()+".mp4");status.setText("Exportando corte "+(count+1)+" de "+((duration+clipMs-1)/clipMs));MediaItem item=new MediaItem.Builder().setUri(source).setClippingConfiguration(new MediaItem.ClippingConfiguration.Builder().setStartPositionMs(start).setEndPositionMs(end).build()).build();try{transformer=new Transformer.Builder(this).setVideoMimeType("video/avc").setAudioMimeType("audio/mp4a-latm").addListener(new Transformer.Listener(){@Override public void onCompleted(Composition composition,ExportResult result){new Thread(()->{try{Uri saved=save(temp);runOnUiThread(()->{count++;remember(saved,count,start,end);card(saved,count,start,end);start=end;progress.setProgress((int)(100*start/duration));next();});}catch(Exception e){runOnUiThread(()->finishJob("Erro ao salvar: "+e.getMessage()));}finally{temp.delete();}}).start();}@Override public void onError(Composition composition,ExportResult result,ExportException error){temp.delete();finishJob("Erro de exportação: "+error.getMessage());}}).build();java.util.List<androidx.media3.common.Effect> effects=new java.util.ArrayList<>();float[] ratios={0f,9f/16f,16f/9f,1f,4f/5f};if(ratioIndex>0)effects.add(androidx.media3.effect.Presentation.createForAspectRatio(ratios[ratioIndex],androidx.media3.effect.Presentation.LAYOUT_SCALE_TO_FIT_WITH_CROP));if(outputHeight>0)effects.add(androidx.media3.effect.Presentation.createForHeight(outputHeight));if(activeStyle>0){java.util.List<androidx.media3.effect.TextureOverlay> overlays=new java.util.ArrayList<>();if(!activeHeadline.isEmpty())overlays.add(textOverlay(activeHeadline,true));if(!activeCaption.isEmpty())overlays.add(textOverlay(activeCaption,false));if(!overlays.isEmpty())effects.add(new androidx.media3.effect.OverlayEffect(com.google.common.collect.ImmutableList.copyOf(overlays)));}transformer.start(new EditedMediaItem.Builder(item).setEffects(new Effects(java.util.Collections.emptyList(),effects)).build(),temp.getAbsolutePath());}catch(Exception e){temp.delete();finishJob("Erro: "+e.getMessage());}}
 private androidx.media3.effect.TextOverlay textOverlay(String value,boolean top){
 android.text.SpannableString text=new android.text.SpannableString(value);
 int color=activeStyle==1?0xffffdf45:activeStyle==3?0xffd8baff:Color.WHITE;
 text.setSpan(new android.text.style.ForegroundColorSpan(color),0,text.length(),0);
 text.setSpan(new android.text.style.BackgroundColorSpan(0xdd101018),0,text.length(),0);
 text.setSpan(new android.text.style.StyleSpan(android.graphics.Typeface.BOLD),0,text.length(),0);
 text.setSpan(new android.text.style.AbsoluteSizeSpan(36),0,text.length(),0);
 androidx.media3.effect.OverlaySettings settings=new androidx.media3.effect.OverlaySettings.Builder().setBackgroundFrameAnchor(0f,top?0.72f:-0.58f).setOverlayFrameAnchor(0f,0f).build();
 return androidx.media3.effect.TextOverlay.createStaticTextOverlay(text,settings);
 }
 private void remember(Uri uri,int number,long from,long to){try{android.content.SharedPreferences prefs=getSharedPreferences("history",MODE_PRIVATE);org.json.JSONArray history=new org.json.JSONArray(prefs.getString("clips","[]"));org.json.JSONObject entry=new org.json.JSONObject();entry.put("uri",uri.toString());entry.put("number",number);entry.put("from",from);entry.put("to",to);history.put(entry);prefs.edit().putString("clips",history.toString()).apply();}catch(Exception ignored){}}
 private void restoreHistory(){try{org.json.JSONArray history=new org.json.JSONArray(getSharedPreferences("history",MODE_PRIVATE).getString("clips","[]"));for(int i=0;i<history.length();i++){org.json.JSONObject e=history.getJSONObject(i);Uri uri=Uri.parse(e.getString("uri"));try(android.os.ParcelFileDescriptor fd=getContentResolver().openFileDescriptor(uri,"r")){if(fd!=null)card(uri,e.getInt("number"),e.getLong("from"),e.getLong("to"));}catch(Exception ignored){}}}catch(Exception ignored){}}
 private Uri save(File file)throws IOException{ContentValues values=new ContentValues();values.put(MediaStore.Video.Media.DISPLAY_NAME,"CortaClip_"+System.currentTimeMillis()+".mp4");values.put(MediaStore.Video.Media.MIME_TYPE,"video/mp4");values.put(MediaStore.Video.Media.RELATIVE_PATH,"Movies/CortaClip");values.put(MediaStore.Video.Media.IS_PENDING,1);Uri uri=getContentResolver().insert(MediaStore.Video.Media.EXTERNAL_CONTENT_URI,values);if(uri==null)throw new IOException("Sem acesso à galeria");try{try(InputStream in=new FileInputStream(file);OutputStream out=getContentResolver().openOutputStream(uri)){if(out==null)throw new IOException("Sem espaço ou acesso");byte[] buffer=new byte[65536];int n;while((n=in.read(buffer))!=-1)out.write(buffer,0,n);}values.clear();values.put(MediaStore.Video.Media.IS_PENDING,0);getContentResolver().update(uri,values,null,null);return uri;}catch(Exception e){getContentResolver().delete(uri,null,null);throw new IOException(e);}}
